import{_ as t,c as e,o as r,ae as n}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"How to Create Chart Manually in Ninja Charts","description":"How to Create Chart Manually in Ninja Charts","frontmatter":{"title":"How to Create Chart Manually in Ninja Charts","description":"How to Create Chart Manually in Ninja Charts"},"headers":[],"relativePath":"guide/ninja-charts/how-to-create-chart-manually-in-ninja-charts.md","filePath":"guide/ninja-charts/how-to-create-chart-manually-in-ninja-charts.md"}'),o={name:"guide/ninja-charts/how-to-create-chart-manually-in-ninja-charts.md"};function h(i,a,s,l,c,u){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="how-to-create-chart-manually-in-ninja-charts" tabindex="-1">How to Create Chart Manually in Ninja Charts <a class="header-anchor" href="#how-to-create-chart-manually-in-ninja-charts" aria-label="Permalink to &quot;How to Create Chart Manually in Ninja Charts&quot;">​</a></h1><p>Want dynamic data charts on your website? Ninja Charts is here for you! This free chart generator in WordPress lets you create and customize all sorts of charts easily. For example, pie charts, line charts, bubble charts, histograms, etc.</p><h2 id="create-a-chart-with-manual-data-input" tabindex="-1">Create a Chart with Manual Data Input <a class="header-anchor" href="#create-a-chart-with-manual-data-input" aria-label="Permalink to &quot;Create a Chart with Manual Data Input&quot;">​</a></h2><ul><li>To create a Manual Chart, click on the <strong>Add New</strong> button from the Ninja Charts dashboard. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Charts-%E2%80%B9-North-%E2%80%94-WordPress-06-03-2025_11_33_AM-2-scaled.webp" alt=""></li><li>Then enter your Chart Name and choose your Chart Renderer. Two types of chart renderers are available: Google Charts &amp; Chart Js. <img src="https://ninjatables.com/wp-content/uploads/2023/10/chart-01-scaled.webp" alt=""></li><li>Now choose your preferred chart type. You can pick any chart type from the 10+ options.</li><li>In the <strong>Data Source</strong> tab, select <strong>Manual Input</strong>. Select and move to the next tab. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Source-02-scaled.webp" alt=""></li><li>In this <strong>Data Range</strong> option, hit the** Add Column** button first to input the data column to the chart. Then <strong>Add Data</strong>. You can add as many data as you want. <img src="https://ninjatables.com/wp-content/uploads/2023/10/data-range-03-scaled.webp" alt=""></li></ul><h3 id="text-input" tabindex="-1">Text Input <a class="header-anchor" href="#text-input" aria-label="Permalink to &quot;Text Input&quot;">​</a></h3><p>This input text can generate the chart label.</p><h3 id="number-input" tabindex="-1">Number Input <a class="header-anchor" href="#number-input" aria-label="Permalink to &quot;Number Input&quot;">​</a></h3><p>The number input can generate chart data. Don’t forget to click the Next button. Now you’ll be moved to the <strong>Formatting &amp; Preview</strong> tab where you can customize the chart in real-time.</p><h2 id="manually-created-chart" tabindex="-1">Manually Created Chart <a class="header-anchor" href="#manually-created-chart" aria-label="Permalink to &quot;Manually Created Chart&quot;">​</a></h2><p>Once you hit Next and move to the <strong>Formatting &amp; Preview</strong> tab, you&#39;ll see the Bar Chart is ready with the data you put manually. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Formatting-Preview-scaled.webp" alt=""> Now, it&#39;s done. <a href="https://ninjatables.com/docs/how-to-customize-charts-in-ninja-charts/" target="_blank" rel="noreferrer">Customize</a> the chart from here all you want. Then hit <strong>Save</strong> and copy the auto-generated shortcode to use on your website. This is how you can easily create Manual Charts using Ninja Charts.</p>',10)])])}const m=t(o,[["render",h]]);export{p as __pageData,m as default};
